import type { CardElement, CardRarity } from "@cardastika/shared";

// Bright-Cut V5 plate construction with Material Shader V7 sprite compositing.
interface BrightCutMaterial {
  id: string; name: string; desc: string; brief: string;
  base: readonly string[]; edge: string; stroke: string; dark: string; light: string;
  shadow: string; punch: string; number: string; numLight: string; metal: boolean; grain: number;
  patina?: string; sheenA?: number; sheenB?: number; noiseOpacity?: number; hammerOpacity?: number;
}
interface ReferenceOptions {
  uid: string; element: CardElement; showArtwork?: boolean; blank?: boolean;
  guides?: boolean; engravingDepth?: number; characterArtSource?: string | null;
}
function escapeXmlAttribute(value: string) {
  return value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;",
  })[character] ?? character);
}

// Map source luminance to the plate material while preserving every alpha/detail value.
function artTintMatrix(materialId: string) {
  const ramps: Readonly<Record<string, readonly [string, string]>> = {
    paper: ["#302015", "#d7b88b"],
    copper: ["#24100d", "#ebae87"],
    bronze: ["#242016", "#e1c891"],
    silver: ["#111b23", "#e5eff0"],
    gold: ["#241407", "#ffe0a0"],
    platinum: ["#0e1720", "#eefbff"],
  };
  const [lowColor, highColor] = ramps[materialId] ?? ramps.silver;
  const rgb = (color: string) => [1, 3, 5].map((index) => parseInt(color.slice(index, index + 2), 16) / 255);
  const low = rgb(lowColor);
  const high = rgb(highColor);

  return low.map((value, index) => {
    const delta = high[index] - value;
    return [0.2126 * delta, 0.7152 * delta, 0.0722 * delta, 0, value]
      .map((coefficient) => coefficient.toFixed(5)).join(" ");
  }).concat("0 0 0 1 0").join(" ");
}
